  padding: 6px 12px;
  border-radius: 4px;
  transition: background 0.2s, color 0.2s;
  white-space: nowrap;
}
.header-nav a:hover { background: #1b1b36; color: #fff; }
.hamburger {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  padding: 4px 8px;
}
.mobile-nav {
  display: none;
  background: #0a0a23;
  border-top: 1px solid #1b1b36;
  padding: 12px 20px;
}
.mobile-nav.active { display: block; }
