/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #1b1b32;
  background: #f5f6f7;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a { text-decoration: none; color: inherit; }
img { max-width: 100%; display: block; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; }

/* ===== Utility ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 20px; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }

/* ===== Header ===== */
.site-header {
  background: #0a0a23;
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 20px;
  max-width: 1200px;
  margin: 0 auto;
}
.logo {
  font-size: 1.25rem;
  font-weight: 800;
  white-space: nowrap;
  letter-spacing: -0.02em;
  color: #fff;
}
.logo span { color: #FEAC32; }
.header-search {
  flex: 1;
  max-width: 420px;
  position: relative;
}
.header-search input {
  width: 100%;
  padding: 8px 14px 8px 36px;
  border-radius: 6px;
  border: none;
  font-size: 0.875rem;
  background: #1b1b36;
  color: #d0d0d0;
  outline: none;
  transition: background 0.2s;
}
.header-search input::placeholder { color: #6e6e8a; }
.header-search input:focus { background: #2a2a4a; }
.header-search .search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #6e6e8a;
  font-size: 0.85rem;
}
.header-nav { display: flex; gap: 8px; align-items: center; }
.header-nav a {
  color: #d0d0d5;
  font-size: 0.9rem;
  padding: 6px 12px;
  border-radius: 4px;
  transition: background 0.2s, color 0.2s;
  white-space: nowrap;
}
.header-nav a:hover { background: #1b1b36; color: #fff; }
.hamburger {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  padding: 4px 8px;
}
.mobile-nav {
  display: none;
  background: #0a0a23;
  border-top: 1px solid #1b1b36;
  padding: 12px 20px;
}
.mobile-nav.active { display: block; }
.mobile-nav a {
  display: block;
  color: #d0d0d5;
  padding: 10px 0;
  font-size: 1rem;
  border-bottom: 1px solid #1b1b36;
}
.mobile-nav a:last-child { border-bottom: none; }
.mobile-nav a:hover { color: #FEAC32; }

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .hamburger { display: block; }
}

/* ===== Banner ===== */
.hero-banner {
  background: #002EAD;
  color: #fff;
  text-align: center;
  padding: 14px 20px;
  font-size: 1rem;
  font-weight: 600;
}
