  gap: 8px;
  font-size: 0.8rem;
  color: #6e6e8a;
}
.card-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #d0d0d0;
  flex-shrink: 0;
  overflow: hidden;
