}
.footer-tags a {
  background: #1b1b36;
  color: #a0a0b8;
  padding: 4px 12px;
  border-radius: 4px;
  font-size: 0.78rem;
  transition: background 0.2s, color 0.2s;
}
.footer-tags a:hover { background: #2a2a4a; color: #FEAC32; }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 24px;
  margin-bottom: 24px;
}
.footer-links a { color: #a0a0b8; font-size: 0.82rem; }
