/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #1b1b32;
  background: #f5f6f7;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a { text-decoration: none; color: inherit; }
img { max-width: 100%; display: block; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; }

/* ===== Utility ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 20px; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }

/* ===== Header ===== */
.site-header {
  background: #0a0a23;
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 20px;
  max-width: 1200px;
  margin: 0 auto;
}
.logo {
  font-size: 1.25rem;
  font-weight: 800;
  white-space: nowrap;
  letter-spacing: -0.02em;
  color: #fff;
}
.logo span { color: #FEAC32; }
.header-search {
  flex: 1;
  max-width: 420px;
  position: relative;
}
.header-search input {
  width: 100%;
  padding: 8px 14px 8px 36px;
  border-radius: 6px;
  border: none;
  font-size: 0.875rem;
  background: #1b1b36;
  color: #d0d0d0;
  outline: none;
  transition: background 0.2s;
}
.header-search input::placeholder { color: #6e6e8a; }
.header-search input:focus { background: #2a2a4a; }
.header-search .search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #6e6e8a;
  font-size: 0.85rem;
}
.header-nav { display: flex; gap: 8px; align-items: center; }
.header-nav a {
  color: #d0d0d5;
  font-size: 0.9rem;
  padding: 6px 12px;
  border-radius: 4px;
  transition: background 0.2s, color 0.2s;
  white-space: nowrap;
}
.header-nav a:hover { background: #1b1b36; color: #fff; }
.hamburger {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  padding: 4px 8px;
}
.mobile-nav {
  display: none;
  background: #0a0a23;
  border-top: 1px solid #1b1b36;
  padding: 12px 20px;
}
.mobile-nav.active { display: block; }
.mobile-nav a {
  display: block;
  color: #d0d0d5;
  padding: 10px 0;
  font-size: 1rem;
  border-bottom: 1px solid #1b1b36;
}
.mobile-nav a:last-child { border-bottom: none; }
.mobile-nav a:hover { color: #FEAC32; }

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .hamburger { display: block; }
}

/* ===== Banner ===== */
.hero-banner {
  background: #002EAD;
  color: #fff;
  text-align: center;
  padding: 14px 20px;
  font-size: 1rem;
  font-weight: 600;
}
.hero-banner a { color: #FEAC32; text-decoration: underline; }

/* ===== Article Cards ===== */
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  padding: 32px 0;
}
@media (max-width: 960px) { .article-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .article-grid { grid-template-columns: 1fr; } }

.article-card {
  background: #fff;
  border-radius: 10px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0,0,0,0.07);
  transition: transform 0.15s, box-shadow 0.15s;
}
.article-card:hover { transform: translateY(-3px); box-shadow: 0 6px 20px rgba(0,0,0,0.12); }
.card-thumb {
  width: 100%;
  height: 180px;
  background: #e8e8ee;
  position: relative;
  overflow: hidden;
}
.card-thumb img { width: 100%; height: 100%; object-fit: cover; }
.card-tag {
  position: absolute;
  top: 12px;
  left: 12px;
  background: #0a0a23;
  color: #FEAC32;
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.card-body { padding: 16px 18px 18px; }
.card-title {
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 12px;
  color: #0a0a23;
}
.card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8rem;
  color: #6e6e8a;
}
.card-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #d0d0d0;
  flex-shrink: 0;
  overflow: hidden;
}
.card-avatar img { width: 100%; height: 100%; object-fit: cover; }

/* Featured card */
.featured-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  background: #fff;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0,0,0,0.09);
  margin: 32px 0 0;
}
.featured-card .card-thumb { height: 100%; min-height: 280px; }
.featured-card .card-body {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 28px 32px;
}
.featured-card .card-title { font-size: 1.5rem; line-height: 1.3; }
.featured-card .card-tag { font-size: 0.75rem; }
@media (max-width: 768px) {
  .featured-card { grid-template-columns: 1fr; }
  .featured-card .card-thumb { min-height: 200px; }
  .featured-card .card-title { font-size: 1.2rem; }
}

/* ===== Section Titles ===== */
.section-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: #0a0a23;
  margin-bottom: 8px;
}

/* ===== Load More ===== */
.load-more-wrap { text-align: center; padding: 24px 0 48px; }
.btn-load-more {
  background: #0a0a23;
  color: #fff;
  border: none;
  padding: 12px 32px;
  border-radius: 6px;
  font-size: 0.95rem;
  font-weight: 600;
  transition: background 0.2s;
}
.btn-load-more:hover { background: #1b1b36; }

/* ===== Tag Page ===== */
.tag-header-section {
  background: #0a0a23;
  color: #fff;
  padding: 48px 0 36px;
}
.tag-header-section h1 {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 4px;
}
.tag-header-section h1 span { color: #FEAC32; }
.tag-header-section .post-count { color: #a0a0b8; font-size: 0.95rem; }
.popular-tags-section {
  padding: 24px 0;
  border-bottom: 1px solid #e0e0e8;
}
.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.popular-tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #fff;
  border: 1px solid #d8d8e4;
  border-radius: 20px;
  padding: 6px 14px;
  font-size: 0.82rem;
  color: #0a0a23;
  transition: border-color 0.2s;
}
.popular-tag-chip:hover { border-color: #FEAC32; }
.popular-tag-chip .count { color: #6e6e8a; font-size: 0.75rem; }

/* ===== Learn Page ===== */
.learn-welcome {
  background: #0a0a23;
  color: #fff;
  padding: 48px 0 40px;
  text-align: center;
}
.learn-welcome h1 {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 10px;
}
.learn-welcome p { color: #a0a0b8; font-size: 1rem; max-width: 500px; margin: 0 auto 16px; }
.btn-gold {
  background: #FEAC32;
  color: #0a0a23;
  border: none;
  padding: 10px 24px;
  border-radius: 6px;
  font-weight: 700;
  font-size: 0.95rem;
  transition: background 0.2s;
}
.btn-gold:hover { background: #e69a28; }

.curriculum-section { padding: 40px 0; }
.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
  margin-top: 20px;
}
.curriculum-card {
  background: #fff;
  border: 1px solid #e0e0e8;
  border-radius: 8px;
  padding: 20px;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.curriculum-card:hover { border-color: #FEAC32; box-shadow: 0 2px 12px rgba(0,0,0,0.06); }
.cert-icon {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background: #f0eeff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  flex-shrink: 0;
}
.curriculum-card h3 { font-size: 0.95rem; font-weight: 700; color: #0a0a23; line-height: 1.35; }

.daily-challenge {
  background: #fffbe6;
  border: 1px solid #f0e4a8;
  border-radius: 10px;
  padding: 28px 32px;
  margin: 32px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
.daily-challenge h3 { font-size: 1.1rem; font-weight: 700; color: #0a0a23; }
.daily-challenge-links a {
  display: inline-block;
  color: #002EAD;
  font-size: 0.88rem;
  margin-right: 16px;
  font-weight: 500;
}
.daily-challenge-links a:hover { text-decoration: underline; }
@media (max-width: 600px) {
  .daily-challenge { flex-direction: column; align-items: flex-start; }
}

.learn-subsection { padding: 32px 0; }
.learn-subsection h2 {
  font-size: 1.25rem;
  font-weight: 700;
  color: #0a0a23;
  margin-bottom: 14px;
}
.learn-subsection ul { list-style: none; }
.learn-subsection li {
  padding: 8px 0;
  border-bottom: 1px solid #ececf0;
  font-size: 0.92rem;
}
.learn-subsection li:last-child { border-bottom: none; }
.learn-subsection li a { color: #002EAD; font-weight: 500; }
.learn-subsection li a:hover { text-decoration: underline; }

/* ===== Donate Page ===== */
.donate-hero {
  background: #0a0a23;
  color: #fff;
  padding: 56px 0 48px;
  text-align: center;
}
.donate-hero h1 { font-size: 2.2rem; font-weight: 800; margin-bottom: 16px; }
.donate-hero p { color: #c8c8dd; font-size: 1.05rem; max-width: 600px; margin: 0 auto; line-height: 1.7; }

.donate-form-section {
  background: #fff;
  max-width: 560px;
  margin: -32px auto 0;
  border-radius: 12px;
  box-shadow: 0 4px 24px rgba(0,0,0,0.1);
  padding: 32px;
  position: relative;
  z-index: 10;
}
.amount-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}
.amount-tab {
  flex: 1;
  padding: 12px 0;
  border: 2px solid #d8d8e4;
  border-radius: 8px;
  background: #fff;
  font-size: 1.1rem;
  font-weight: 700;
  color: #0a0a23;
  text-align: center;
  transition: border-color 0.2s, background 0.2s, color 0.2s;
}
.amount-tab.active {
  border-color: #FEAC32;
  background: #FEAC32;
  color: #0a0a23;
}
.amount-tab:hover:not(.active) { border-color: #c0b070; }
.donate-description {
  font-size: 0.95rem;
  color: #3a3a52;
  text-align: center;
  margin-bottom: 20px;
  line-height: 1.6;
}
.btn-donate {
  width: 100%;
  background: #FEAC32;
  color: #0a0a23;
  border: none;
  padding: 14px;
  border-radius: 8px;
  font-size: 1.1rem;
  font-weight: 700;
  transition: background 0.2s;
}
.btn-donate:hover { background: #e69a28; }
.donate-sub {
  text-align: center;
  font-size: 0.8rem;
  color: #6e6e8a;
  margin-top: 10px;
}

.benefits-section, .initiatives-section, .achievements-section {
  padding: 48px 0;
}
.benefits-section h2, .initiatives-section h2, .achievements-section h2 {
  font-size: 1.5rem;
  font-weight: 800;
  color: #0a0a23;
  margin-bottom: 20px;
  text-align: center;
}
.benefits-list {
  max-width: 560px;
  margin: 0 auto;
  list-style: none;
}
.benefits-list li {
  padding: 12px 0;
  border-bottom: 1px solid #ececf0;
  font-size: 0.95rem;
  display: flex;
  align-items: flex-start;
  gap: 10px;
}
.benefits-list li::before {
  content: '✓';
  color: #2ea44f;
  font-weight: 700;
  flex-shrink: 0;
}

.initiatives-list {
  max-width: 600px;
  margin: 0 auto;
  list-style: none;
}
.initiatives-list li {
  padding: 12px 0;
  border-bottom: 1px solid #ececf0;
  font-size: 0.95rem;
  display: flex;
  align-items: flex-start;
  gap: 10px;
}
.initiatives-list li::before {
  content: '→';
  color: #FEAC32;
  font-weight: 700;
  flex-shrink: 0;
