.achievement-item {
  background: #fff;
  border: 1px solid #e0e0e8;
  border-radius: 8px;
  padding: 20px;
  text-align: center;
}
.achievement-item .stat { font-size: 1.5rem; font-weight: 800; color: #0a0a23; }
.achievement-item .label { font-size: 0.85rem; color: #6e6e8a; margin-top: 4px; }

/* FAQ Accordion */
.faq-section { padding: 48px 0 64px; }
.faq-section h2 {
  font-size: 1.5rem;
  font-weight: 800;
  color: #0a0a23;
  margin-bottom: 20px;
  text-align: center;
}
.faq-list { max-width: 700px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid #e0e0e8;
}
.faq-question {
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  padding: 16px 0;
  font-size: 0.95rem;
  font-weight: 600;
  color: #0a0a23;
